const fmt = (n:number) => new Intl.NumberFormat('en-IN', { maximumFractionDigits:0 }).format(n);
const inr = (n:number) => n>=1e7?`₹${+(n/1e7).toFixed(2)} crore`:n>=1e5?`₹${+(n/1e5).toFixed(2)} lakh`:`₹${fmt(n)}`;
const termText = (min:number,max:number) => max>60?`Up to ${+(max/12).toFixed(1)} years`:min===max?`${max} months`:`${min}–${max} months`;
const slugOf = (id:string) => id==='property'?'loan-against-property':id;
const fmtDate = (d:string) => new Intl.DateTimeFormat('en-IN',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(d));
const errMsg = (x:unknown) => x instanceof ApiError ? x.message : 'Something went wrong. Please try again.';

// The built-in text above is the fallback. When the server answers, its loan products and company details replace it.
function useLoans(){
  const live=useApiLoanTypes();
  return useMemo(()=>{
    if(!live) return loanTypes.map(l=>({...l,dbId:0}));
    return loanTypes.flatMap(l=>{
      const t=live.find((x:LoanTypeApi)=>x.slug===slugOf(l.id));
      if(!t) return [];
      return [{...l,dbId:t.id,amount:`${inr(t.min_amount)} – ${inr(t.max_amount)}`,rate:`From ${t.min_rate}% p.a.*`,term:termText(t.min_tenure,t.max_tenure),min:t.min_amount,max:t.max_amount,annualRate:t.min_rate,maxMonths:t.max_tenure,eligibility:t.eligibility_text||l.eligibility,documents:t.required_docs.length?t.required_docs.map(d=>DOC_LABEL[d]??d).join(', '):l.documents}];
    });
  },[live]);
}
function useConfig(){
  const s=useSite();
  return {...config,company:s.company??config.company,nbfc:s.nbfc??config.nbfc,grievance:s.grievance??config.grievance,supportEmail:s.email??config.supportEmail,phone:s.phone??config.phone,whatsapp:s.whatsapp??config.whatsapp,address:s.address??config.address,consent:s.consentText??config.consent,consentVersion:s.consentVersion??''};
}

function ButtonLink({ href, children, secondary=false, testid }: { href:string;children:ReactNode;secondary?:boolean;testid?:string }) {
  return <Link href={href} className={`btn ${secondary?'btn-outline':'btn-primary'}`} data-testid={testid}>{children}<ArrowRight size={16}/></Link>;
}

